def load_concept_matrix(num_class):
    if num_class == 60:
        spatial_names = [
            'head', 'head', 'head', 'head', 'head', 'head',
            'hand', 'hand', 'hand', 'hand', 'hand', 'hand', 'hand', 'hand', 'hand', 'hand', 'hand',
            'arm', 'arm', 'arm', 'arm', 'arm', 'arm', 'arm', 'arm', 'arm', 'arm', 'arm',
            'hip', 'hip', 'hip', 'hip', 'hip', 'hip', 'hip', 'hip',
            'leg', 'leg', 'leg', 'leg', 'leg', 'leg', 'leg', 'leg', 'leg',
            'foot', 'foot', 'foot', 'foot', 'foot', 'foot', 'foot',
            'interaction_two_person'
        ]
        return CONCEPT_MATRIX, 53, 21, spatial_names
    
    # Check for custom concept matrix CSV (e.g., anubis_concepts.csv)
    csv_path = os.path.join(os.path.dirname(__file__), 'anubis_concepts.csv')
    if os.path.exists(csv_path):
        try:
            matrix = []
            spatial_names = []
            temporal_names = []
            with open(csv_path, 'r', encoding='utf-8') as f:
                reader = csv.reader(f)
                header = next(reader)
                
                # Identify spatial vs temporal concepts dynamically from headers
                for col_name in header[1:]:
                    if col_name.startswith('temporal_') or col_name.startswith('temp_'):
                        temporal_names.append(col_name)
                    else:
                        spatial_names.append(col_name)
                        
                for row in reader:
                    matrix.append([float(x) for x in row[1:]])
            if len(matrix) == num_class:
                print(f"Successfully loaded concept matrix with {len(spatial_names)} spatial and {len(temporal_names)} temporal concepts.")
                return matrix, len(spatial_names), len(temporal_names), spatial_names
            else:
                print(f"Warning: Concept matrix rows ({len(matrix)}) mismatch class count ({num_class}). Using zero matrix.")
        except Exception as e:
            print(f"Error loading custom concept matrix CSV: {e}")
            
    # Fallback to zero matrix
    spatial_names = ['interaction_two_person'] * 53
    return [[0.0] * 74 for _ in range(num_class)], 53, 21, spatial_names




